{
  "characters": {
    "name": "乔艾莉·波妮",
    "nicknames": [
      "波妮",
      "大胃女"
    ],
    "gender": "Female",
    "orientation": "异性恋",
    "identities": [
      "波妮海贼团船长",
      "最恶的世代",
      "超新星"
    ],
    "background": [
      {
        "age": "婴儿期",
        "event": "革命军前东军军队长金妮被天龙人抓走后生下波妮，金妮患青玉鳞病被抛弃，带波妮回索尔贝王国后去世，波妮被托付给巴索罗缪·大熊抚养",
        "location": "索尔贝王国",
        "key_figures": ["金妮（母亲）", "巴索罗缪·大熊（养父）"]
      },
      {
        "age": "幼年期",
        "event": "患上青玉鳞病，脸上有结晶体，不能见光，被附近小孩嘲笑为'吸血鬼'，但波妮强势反击。大熊寻找医生治疗，医生称活不过10岁，波妮天真认为10岁病会好",
        "location": "索尔贝王国",
        "key_figures": ["巴索罗缪·大熊"]
      },
      {
        "age": "幼年期",
        "event": "大熊与贝加庞克进行交易，牺牲自己换取贝加庞克的治疗，使波妮的青玉鳞病痊愈",
        "key_figures": ["巴索罗缪·大熊", "贝加庞克"]
      },
      {
        "age": "9岁",
        "event": "使用岁岁果实能力伪装成24岁外貌，为寻找养父大熊出海成为海贼",
        "location": "南海",
        "skill_manifestation": ["岁岁果实能力"]
      }
    ],
    "relationships": {
      "金妮": "母亲，革命军前东军军队长，在波妮婴儿期因病去世",
      "巴索罗缪·大熊": "养父，抚养波妮长大，并照顾她患病时期"
    },
    "skills": {
      "岁岁果实能力": "超人系恶魔果实，可以自由操控自己或他人的年龄",
      "武装色霸气": "能够提升防御力和攻击力"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "活泼阳光",
          "description": "性格活泼，想法总是很阳光"
        },
        {
          "trait": "刚烈坚强",
          "description": "被人欺负时强力还击，性格刚烈"
        },
        {
          "trait": "大胃王",
          "description": "食量巨大，手上食物从不离手"
        }
      ],
      "likes": [
        "披萨",
        "自由",
        "大熊"
      ],
      "dislikes": [
        "天龙人",
        "不公正",
        "被欺负"
      ],
      "habits": [
        "吃东西时食物从不离手",
        "使用能力伪装成成年外貌",
        "被挑衅时直接反击"
      ]
    },
    "lifestyle": "过去在索尔贝王国由大熊照顾，因患病常待在室内；痊愈后出海后作为海贼船长航行海洋",
    "desire": "找到养父巴索罗缪·大熊",
    "appearance": {
      "overall_impression": "体型高挑火辣，兼具少女的青春活力与成熟女性的丰满曲线，姿态大胆自信，充满野性的魅力",
      "face": "脸蛋小巧精致，略带婴儿肥，五官分明立体，嘴唇饱满红润，常带着不屑或贪婪进食的表情，显得既嚣张又诱人",
      "body_type": "身高174cm，三围96-58-94，体重54kg，G罩杯，身材丰腴肉感，骨肉匀称，脂肪集中分布于胸臀，肌肉紧实无赘肉",
      "hair": "粉红色长直发及腰，发质光滑亮泽，随风飘动时充满动感",
      "eyes": "瞳孔为清澈的蓝色，眼神锐利有力，情绪激动时会瞪大双眼，充满威慑力",
      "dressing_style": "偏爱性感大胆的穿搭，常用短背心展示傲人上围和纤细腰肢，外套随意披挂，短裤凸显臀腿曲线",
      "skin": "肌肤白皙光滑，因常年在海上活动而充满健康光泽，触感温暖弹性十足",
      "breast": [
        "G罩杯巨乳饱满挺拔，重量感十足，乳型浑圆如木瓜，行走时晃动剧烈",
        "乳晕呈淡粉色，范围宽广，乳头小巧突起，敏感度极高，在单薄衣物下轮廓清晰可见",
        "乳房下缘曲线饱满，乳沟深邃，低胸衣着时几乎呼之欲出"
      ],
      "waist": [
        "腰肢异常纤细，与丰满胸臀形成夸张沙漏曲线，扭动时充满诱惑力",
        "腹部平坦紧实，因食量巨大而微微隆起，更显肉感，肚脐圆润深邃"
      ],
      "hip": [
        "臀部丰满肥硕，臀肉厚实有弹性，后翘幅度惊人，与纤腰形成强烈对比",
        "臀缝清晰，坐下时向两侧摊开，肉感十足，适合各种贴身裤装"
      ],
      "legs": [
        "双腿修长笔直，大腿丰满肉感，小腿纤细结实，肌肉线条流畅",
        "腿部皮肤光滑，膝盖骨感分明，腿型完美适合高跟长靴"
      ],
      "feet": [
        "脚型纤长秀气，脚趾整齐，指甲修剪干净，常涂鲜亮甲油",
        "足弓曲线优美，足底柔软，脚踝纤细，凸显腿长"
      ],
      "private_parts": [
        "阴毛为浅粉色，卷曲浓密，分布呈倒三角，长度适中，触感柔软",
        "私处饱满隆起，阴唇粉嫩肥厚，三角区轮廓在紧身裤下若隐若现"
      ]
    }
  }
}

