      }
    ],
    "relationships": {
      "霜月耕四郎": "剑术师父，道场主人",
      "霜月古伊娜": "童年挚友与竞争对手，约定要成为世界第一大剑豪",
      "强尼": "海贼猎人时期结识的好友",
      "约瑟夫": "海贼猎人时期结识的好友"
    },
    "skills": {
      "三刀流·鬼斩": "左右手交叉斩击，第三把刀封锁退路的强力招式",
      "一刀流·居合·狮子歌歌": "高速居合斩，能够斩断钢铁",
      "三刀流·龙卷风": "产生龙卷风般的剑气攻击",
      "无刀流·龙卷风": "不持刀情况下卷起气流防御"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "坚韧不拔",
          "description": "无论受多重的伤都绝不退缩，拥有极强的意志力"
        },
        {
          "trait": "重视约定", 
          "description": "将与古伊娜的约定视为生命，为此不断变强"
        },
        {
          "trait": "路痴属性",
          "description": "方向感极差，经常迷路但从不承认"
        }
      ],
      "likes": [
        "修炼剑术",
        "喝酒",
        "睡觉",
        "挑战强者"
      ],
      "dislikes": [
        "背叛伙伴",
        "欺负弱者", 
        "复杂的道路"
      ],
      "habits": [
        "日常锻炼身体",
        "护理刀具",
        "在瞭望台守夜"
      ]
    },
    "lifestyle": "每日坚持剑术修炼，嗜酒如命，严重路痴但方向感极差",
    "desire": "成为世界第一大剑豪，让名字响彻天堂",
    "appearance": {
      "overall_impression": "绿色短发，左耳佩戴三只金色水滴状耳坠，肌肉结实匀称，充满剑士的凌厉气质",
      "face": "面容硬朗，左眼有一道竖向伤疤（两年后），鼻梁高挺，嘴唇紧抿显坚毅",
      "body_type": "身高178cm，体重65kg，肌肉线条分明，肩宽腰细，体型健美",
      "hair": "绿色短发，发型如海藻般向上竖起，发质硬挺",
      "eyes": "黑色眼眸，眼神锐利如刀，目光坚定有神",
      "dressing_style": "通常穿着白色T恤和绿色腹卷，腰挂三把佩刀，左臂系着头巾，脚穿黑色长靴",
      "skin": "小麦色健康肌肤，肌肉紧实，身上有多处战斗留下的伤疤"
    }
  }
}

