{
  "characters": {
    "name": "妮可·罗宾",
    "nicknames": [
      "恶魔之子",
      "Miss All Sunday"
    ],
    "gender": "Female",
    "orientation": "异性恋",
    "identities": [
      "奥哈拉的唯一幸存者",
      "考古学家",
      "巴洛克工作社副社长"
    ],
    "background": [
      {
        "age": "婴儿期",
        "event": "出生在西海奥哈拉，父亲早逝，由母亲妮可·欧尔比雅抚养",
        "location": "奥哈拉",
        "key_figures": [
          "妮可·欧尔比雅（母亲）"
        ]
      },
      {
        "age": "2岁",
        "event": "母亲出海寻找历史正文，将罗宾寄宿在舅舅奥朗家，开始遭受舅妈罗吉的冷遇",
        "location": "奥哈拉",
        "key_figures": [
          "奥朗（舅舅）",
          "罗吉（舅妈）"
        ]
      },
      {
        "age": "2-8岁",
        "event": "在全知树图书馆学习考古学，展示超凡天赋，8岁时以满分获得考古学博士学位，但因恶魔果实能力被当地人歧视",
        "location": "奥哈拉",
        "key_figures": [
          "克劳·D·三叶草（老师）"
        ],
        "skill_manifestation": [
          "考古学知识",
          "花花果实基础运用"
        ]
      },
      {
        "age": "8岁",
        "event": "奥哈拉事件爆发，世界政府发动屠魔令，母亲欧尔比雅和好友萨乌罗死亡，罗宾成为唯一幸存者，被悬赏7900万贝里，开始逃亡生涯",
        "location": "奥哈拉",
        "key_figures": [
          "妮可·欧尔比雅",
          "哈古瓦尔·D·萨乌罗",
          "库赞（青雉）"
        ],
        "turning_point": {
          "loss": "母亲和萨乌罗死亡",
          "exile": "被迫成为逃亡者"
        }
      },
      {
        "age": "8-24岁",
        "event": "为生存辗转于地下世界，多次被出卖，但持续寻找历史正文，并提升花花果实能力",
        "location": "世界各地",
        "skill_manifestation": [
          "暗杀技巧",
          "潜伏能力"
        ]
      },
      {
        "age": "24岁",
        "event": "加入巴洛克工作社，担任副社长，代号Miss All Sunday，为克洛克达尔工作",
        "location": "伟大航道",
        "key_figures": [
          "沙·克洛克达尔"
        ]
      }
    ],
    "relationships": {
      "妮可·欧尔比雅": "母亲，考古学家，在奥哈拉事件中死亡",
      "奥朗": "舅舅，收养罗宾但家庭冷遇",
      "罗吉": "舅妈，对罗宾苛刻",
      "米子伊拉": "表妹",
      "克劳·D·三叶草": "老师，全知树图书馆馆长",
      "哈古瓦尔·D·萨乌罗": "好友，巨人族，在奥哈拉事件中保护罗宾",
      "库赞": "原海军大将，放走罗宾并关注其生涯"
    },
    "skills": {
      "花花果实能力": "能让身体任何部位像开花一样长在视线范围内的物体上，用于攻击或侦查",
      "考古学": "能解读历史正文，拥有丰富历史知识",
      "暗杀": "在逃亡中练就的隐蔽攻击技巧"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "冷静理性",
          "description": "情绪稳定，遇事沉着分析。"
        },
        {
          "trait": "智慧博学",
          "description": "知识渊博，擅长策略思考。"
        },
        {
          "trait": "善良隐忍",
          "description": "内心柔软，能为重要目标忍受痛苦。"
        },
        {
          "trait": "疏离警惕",
          "description": "因过去背叛经历，对他人保持距离。"
        }
      ],
      "likes": [
        "历史正文",
        "考古研究",
        "三明治",
        "咖啡"
      ],
      "dislikes": [
        "世界政府",
        "不公正",
        "背叛行为"
      ],
      "habits": [
        "阅读书籍时极度专注",
        "习惯用花瓣能力侦查环境",
        "每日洗澡保持清洁"
      ]
    },
    "lifestyle": "逃亡期间隐藏身份，辗转于不同组织，利用考古知识谋生，偶尔从事暗杀活动",
    "desire": "找到所有历史正文，解读空白一百年的真相",
    "appearance": {
      "overall_impression": "身材高挑丰腴的成熟女性，体态婀娜曲线夸张，姿态优雅中带着致命的诱惑，小麦色肌肤散发着异域风情",
      "face": "标准的鹅蛋脸，五官立体分明，鼻梁高挺，嘴唇丰厚饱满呈深红色，肤色呈健康的小麦色，面部线条柔和诱人",
      "body_type": "身高188cm，三围100-60-90，体重59kg，J罩杯，身材比例极度夸张，肉感与骨感结合完美，丰乳肥臀细腰",
      "hair": "黑色齐肩短发，发梢挑染墨蓝色，发质顺滑有光泽，衬托出颈部和锁骨的优美线条",
      "eyes": "深蓝色瞳孔如深邃海洋，眼神深邃充满知性与神秘感，睫毛长而浓密",
      "dressing_style": "紫色深V露脐上衣紧紧包裹呼之欲出的巨乳，短裙凸显圆润臀部曲线，长靴衬托修长双腿，整体着装大胆凸显身材优势",
      "skin": "全身肌肤呈均匀小麦色，触感光滑细腻如绸缎，肌肤紧实富有弹性",
      "breast": [
        "J罩杯巨乳丰满硕大沉重，形状如成熟蜜瓜般浑圆下垂，乳肉柔软且弹性十足，行走时晃动感明显",
        "乳晕呈深褐色直径较大，乳头深色且常因敏感处于微勃状态，乳沟深邃如同深渊，从衣领处呼之欲出"
      ],
      "waist": [
        "腰肢异常纤细紧实，与夸张的胸臀形成强烈对比，马甲线清晰可见，扭动时柔软无骨",
        "肚脐呈水平椭圆形，深邃清晰，周围皮肤光滑紧绷，腹部平坦有力"
      ],
      "hip": [
        "臀部丰满肥硕如蜜桃，臀肉结实饱满且充满肉感，后翘弧度惊人，坐下时向两侧摊开面积广大",
        "臀缝深陷线条分明，与纤细腰身连接处的腰臀曲线极度夸张，充满母性诱惑"
      ],
      "legs": [
        "双腿修长笔直长度惊人，大腿丰满肉感十足，小腿纤细跟腱明显，肌肉线条流畅不失柔软",
        "腿部皮肤光滑无瑕，膝盖骨感小巧，从裙摆下延伸出的腿部线条诱惑力十足"
      ],
      "feet": [
        "脚型修长标准，脚趾整齐纤细指甲修剪圆润，常涂深红色甲油，足弓曲线优美",
        "脚底柔软略带茧子更显真实，脚踝纤细骨感明显，适合被手掌握住把玩"
      ],
      "private_parts": [
        "阴毛浓密卷曲呈深黑色，分布区域广泛呈倒三角形，毛发硬挺有弹性",
        "私处部位饱满隆起如馒头，阴唇肥厚呈深褐色，三角区区域开阔肉感充盈"
      ]
    }
  }
}

