      "face": "精致娃娃脸搭配立体五官，鼻梁纤细挺拔，嘴唇粉嫩饱满如花瓣，肤色白皙透亮，第三只眼闭合时形成垂直细缝更显神秘，表情常在纯真与妩媚间切换",
      "body_type": "身高166cm，三围84-56-86，体重45kg，体型娇小但曲线分明，骨架纤细柔韧，肌肉柔软富有弹性，腰臀比突出",
      "hair": "金色及腰双马尾，发尾呈现自然卷曲，刘海刻意设计为左长右短以遮挡第三只眼，发丝柔顺有光泽，随风摆动时散发甜美香气",
      "eyes": "左右双眼为大而圆的蓝色瞳孔，第三只眼呈深紫色竖瞳，三只眼睛同时睁开时目光极具穿透力，睫毛长而卷翘如蝶翼",
      "dressing_style": "粉色蕾丝连衣裙搭配白色荷叶边围裙，裙摆采用多层薄纱设计，行动时隐约透出腿部曲线，胸前大型蝴蝶结突出胸部轮廓，棕色系带长靴凸显纤细脚踝",
      "skin": "肌肤如奶油般白皙丝滑，皮下脂肪分布均匀形成柔软触感，关节处呈现淡粉色，全身肤质细腻无毛孔，接触时能闻到淡淡巧克力香",
      "breast": [
        "B罩杯乳房小巧圆润，形状如倒扣玉碗，乳尖自然上翘，乳晕呈淡粉色且范围较小",
        "穿戴束胸衣时形成自然沟壑，布料摩擦时乳头明显凸起，运动时起伏幅度柔和富有韵律",
        "乳房基底轮廓清晰，与纤细锁骨形成优美过渡，俯身时领口微敞展现若隐若现的曲线"
      ],
      "waist": [
        "腰身纤细不足一握，马甲线若隐若现，两侧腰窝深邃，扭转时呈现迷人弧度",
        "肚脐呈小巧圆形，周围皮肤紧致无痕，围裙系带勒紧时更显腰部曲线"
      ],
      "hip": [
        "臀部饱满如蜜桃，臀肉紧实有弹性，后腰与臀峰形成流畅S型曲线",
        "裙撑支撑下臀型更显圆润，坐姿时裙摆自然铺展凸显肉感"
      ],
      "legs": [
        "双腿匀称修长，大腿肌肉线条柔和，小腿纤细脚踝玲珑",
        "过膝长靴与绝对领域形成绝对领域，腿部皮肤光滑如缎"
      ],
      "feet": [
        "足型纤巧足弓优美，脚趾整齐如贝珠，指甲涂有淡粉甲油",
        "长靴包裹下足部曲线依然分明，行走时步态轻盈如猫"
      ],
      "private_parts": [
        "阴毛为浅金色卷曲绒毛，分布稀疏呈三角状，长度较短如天鹅绒质感",
        "耻骨部位饱满隆起，阴唇粉嫩闭合紧密，敏感度极高"
      ]
    }
  }
