{
  "characters": {
    "name": "凯多",
    "nicknames": [
      "百兽凯多",
      "最强生物"
    ],
    "gender": "男",
    "orientation": "异性恋",
    "identities": [
      "百兽海贼团总督",
      "四皇",
      "鱼鱼果实·幻兽种·青龙形态能力者"
    ],
    "background": [
      {
        "age": "少年期",
        "event": "出身于沃卡王国，10岁时成为该国最强战士，后因国王出卖被交给海军，但多次逃脱并开始海贼生涯",
        "location": "沃卡王国",
        "key_figures": ["沃卡国王"]
      },
      {
        "age": "青年期",
        "event": "15岁加入洛克斯海贼团，参与神之谷事件，后脱离洛克斯并获得鱼鱼果实能力，逐渐组建自己的势力",
        "location": "海贼岛哈奇诺斯、神之谷",
        "key_figures": ["洛克斯·D·吉贝克", "夏洛特·玲玲"]
      },
      {
        "age": "成年期",
        "event": "与和之国将军黑炭大蛇合作，盘踞鬼之岛，击败光月御田并统治和之国，打造百兽海贼团",
        "location": "和之国、鬼之岛",
        "key_figures": ["黑炭大蛇", "光月御田", "赤鞘九侠"]
      }
    ],
    "relationships": {
      "大和": "女儿",
      "夏洛特·玲玲": "好友，原洛克斯海贼团同伴",
      "黑炭大蛇": "合作者，和之国将军",
      "光月御田": "宿敌，给其留下永久伤疤",
      "烬": "心腹，百兽海贼团三大灾害之一"
    },
    "skills": {
      "雷鸣八卦": "以极快速度用缠绕霸气的狼牙棒打击对手，威力巨大",
      "热息": "口吐高热火焰，攻击距离长，可蒸发山脉",
      "坏风": "从口中吐出风刃切割敌人，锋利如镰鼬",
      "龙卷风": "旋转龙躯产生巨大龙卷风，造成范围伤害",
      "霸海": "与夏洛特·玲玲的合击技，发出冲击波毁灭前方区域"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "喜怒无常",
          "description": "情绪变化剧烈，时而痛哭时而暴怒，行为难以预测"
        },
        {
          "trait": "崇尚暴力",
          "description": "相信战争决定价值，企图发动顶级战争毁灭世界"
        },
        {
          "trait": "精明计策",
          "description": "表面粗犷，实则善于谋划，如利用和之国资源"
        }
      ],
      "likes": [
        "喝酒",
        "自杀尝试",
        "招揽强力部下",
        "战争与混乱"
      ],
      "dislikes": [
        "无聊的世界",
        "弱小的对手",
        "欺骗与背叛"
      ],
      "habits": [
        "随身携带酒葫芦饮酒",
        "尝试各种方式自杀",
        "通过战斗测试对手实力"
      ]
    },
    "lifestyle": "作为海贼总督日常饮酒、策划战争，盘踞鬼之岛处理事务，时常独自挑战强敌或自杀",
    "desire": "发动世界上最顶级的战争，毁灭现有秩序，建立无政府的海贼帝国",
    "appearance": {
      "overall_impression": "身材高大魁梧，高710厘米，黑发披肩，头长龙角，嘴有龙须胡须，左臂有龙鳞纹身，肌肉发达",
      "face": "面容粗犷，鼻梁高挺，嘴唇厚实，肤色偏深，目光锐利",
      "body_type": "体型健壮，右腹有X字伤疤，肌肉线条分明，无赘肉",
      "hair": "黑色长发，披散至肩，质地粗糙",
      "eyes": "瞳孔呈红色，眼神凶狠，带有压迫感",
      "dressing_style": "上半身赤裸，腰挂紫色上衣，下着墨绿色宽裤，披紫色绒毛披风，腰系注连绳",
      "skin": "肌肤坚韧，带有龙鳞质感，右腹伤疤明显，触感粗糙"
    }
  }
}

