        "key_figures": ["安布里奥·伊万科夫", "巴索罗缪·大熊"]
      },
      {
        "age": "成年期",
        "event": "在哥亚王国目睹贫民窟火灾，救下受伤的萨博，并决心扩大革命军规模，对抗世界政府",
        "location": "东海哥亚王国",
        "key_figures": ["萨博"]
      }
    ],
    "relationships": {
      "蒙奇·D·卡普": "父亲，海军本部中将",
      "蒙奇·D·路飞": "儿子，草帽海贼团船长",
      "萨博": "革命军同志，如同弟子般照顾",
      "安布里奥·伊万科夫": "革命军同伴，好友",
      "巴索罗缪·大熊": "革命军同伴，好友"
    },
    "skills": {
      "革命领导": "作为革命军总司令，擅长战略规划和组织动员，连续推翻数十个王国暴政",
      "战斗技巧": "精通武器使用和格斗术，曾在海军训练中掌握多种战斗技能",
      "风之掌控": "疑似拥有操控天气的能力，能引发强风干扰战局"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "沉稳冷静",
          "description": "性格冷静沉着，做事滴水不漏，即使在危机中也能保持镇定"
        },
        {
          "trait": "野心远大",
          "description": "怀有推翻世界政府、建立自由平等新世界的远大志向"
        },
        {
          "trait": "谨慎隐秘",
          "description": "不轻易透露个人过去，保护革命事业安全"
        }
      ],
      "likes": [
        "自由",
        "平等",
        "喝茶",
        "牛奶蛋糕"
      ],
      "dislikes": [
        "暴政",
        "不平等",
        "欺骗"
      ],
      "habits": [
        "处理革命军文件",
        "闲暇时喝茶思考",
        "帮助萨博修行"
      ]
    },
    "lifestyle": "日常忙于处理革命军事务，经常熬夜批阅文件，喜欢在工作时饮用热茶，偶尔食用牛奶蛋糕作为休闲",
    "desire": "推翻世界政府暴政，消灭贵族阶级，建立自由、平等、和谐的新世界",
    "appearance": {
      "overall_impression": "身材高大威严，面容凶狠严肃，左脸有红色方纹刺青，整体散发压迫感",
      "face": "方脸型，左脸颊有红色方纹刺青，无眉毛，下巴留胡茬，表情常显凶狠",
      "body_type": "身高256厘米，体型魁梧健壮，肌肉结实，肩宽腰粗，站立时姿态挺拔",
      "hair": "黑色短发，发质硬直，凌乱向后梳理，露出额头",
      "eyes": "深色瞳孔，眼神锐利有神，略带皱纹",
      "dressing_style": "常穿深绿色大衣，内搭暗色西服和橘黄色衬衫，服装简洁实用，突出革命者形象",
      "skin": "肤色偏深，质地粗糙，有岁月痕迹，触感坚韧"
    }
  }
}

