    "appearance": {
      "overall_impression": "体型高大健壮，身高240cm，蓝色飞机头发型，机械改造身体凸显力量感，风格休闲暴露",
      "face": "方脸，下巴呈M型，铁制鼻子，常戴墨镜遮挡眼睛",
      "body_type": "肌肉发达，双臂为机械结构，腹部内置冰箱可储存饮料，体重因改造未知但显魁梧",
      "hair": "蓝色短发呈飞机头造型，发质坚硬，可随可乐能量改变发型",
      "eyes": "隐藏在墨镜后，细节不明但眼神锐利",
      "dressing_style": "常穿彩色花衬衫和蓝色三角泳裤，腰系皮带，脚踩凉鞋，突出机械身体",
      "skin": "部分为机械金属光泽，部分人类皮肤呈健康肤色，触感坚硬与柔软并存"
    }
  }
}

