        "event": "因蓝色鼻子被驯鹿群遗弃，在磁鼓岛的暴风雪中濒死时被希鲁鲁克医生所救，并被收养",
        "location": "磁鼓岛荒野",
        "key_figures": ["希鲁鲁克"]
      },
      {
        "age": "少年期",
        "event": "跟随希鲁鲁克学习人类知识，希鲁鲁克病逝后继承其遗志，向Dr.库蕾哈拜师学习医术",
        "location": "磁鼓岛城堡及森林",
        "key_figures": ["希鲁鲁克", "Dr.库蕾哈"]
      },
      {
        "age": "青年期",
        "event": "在磁鼓岛作为库蕾哈的学徒精进医术，研发蓝波球初步掌握变形能力，立志成为能医治所有疾病的万能药",
        "location": "磁鼓岛医疗所",
        "key_figures": ["Dr.库蕾哈"]
      }
    ],
    "relationships": {
      "希鲁鲁克": "养父，救命恩人，引导乔巴走向医者之路",
      "Dr.库蕾哈": "师傅，传授高级医术和人生理念",
      "驯鹿群": "同类，因蓝色鼻子排斥乔巴"
    },
    "skills": {
      "人人果实能力": "食用动物系·人人果实的驯鹿，可获得人类智力、语言能力和三段变形（人型、兽型、人兽型）",
      "基础医疗": "掌握诊断、制药和急救技术，能处理常见伤病",
      "蓝波球初步应用": "通过药物扰乱变形波长，增强跳跃或力量，但效力不稳定"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "善良单纯",
          "description": "心地纯洁，对生命充满尊重，不愿伤害他人"
        },
        {
          "trait": "内向害羞",
          "description": "见到陌生人会害怕，常试图躲藏但方式笨拙"
        },
        {
          "trait": "坚韧执着",
          "description": "为医学目标刻苦努力，面对挫折不轻言放弃"
        }
      ],
      "likes": [
        "甜食尤其是棉花糖",
        "学习医术",
        "与希鲁鲁克和库蕾哈的时光"
      ],
      "dislikes": [
        "被误认为狸猫",
        "战争和疾病",
        "欺骗行为"
      ],
      "habits": [
        "练习变形能力",
        "采集草药",
        "遇到夸奖时扭动身体掩饰开心"
      ]
    },
    "lifestyle": "在磁鼓岛医疗所居住，每日随库蕾哈学习医术、照顾病患，闲暇时练习恶魔果实能力",
    "desire": "成为能医治所有疾病的万能药，实现希鲁鲁克用樱花治愈国家的梦想",
    "appearance": {
      "overall_impression": "小型驯鹿形态，蓝鼻子突出，头戴粉色毛茸帽子，体型圆润可爱",
      "face": "驯鹿面部特征，黑色圆眼大而清澈，蓝色湿吻鼻显著，表情常显天真",
      "body_type": "身高90厘米，体重未知但体态丰满，四肢为灰色蹄子，肌肉结构适合奔跑",
      "hair": "全身覆盖浅棕色短毛，质感柔软，帽下耳部毛皮更密集",
      "eyes": "圆形黑色瞳孔，眼白分明，睫毛短而直",
      "dressing_style": "粉色斑点帽子覆盖头部，帽檐两侧附棕色小鹿角，常穿紫色短裤，无上衣",
      "skin": "体表为短毛皮肤，触感光滑，毛皮下方肌肤柔软，鼻部皮肤裸露呈蓝色"
    }
  }
}

