        "location": "鱼人岛鱼人街",
        "key_figures": ["费舍尔·泰格", "恶龙"]
      },
      {
        "age": "青年期",
        "event": "加入龙宫王国尼普顿军队，成为精锐士兵，后因费舍尔·泰格回归而退出军队",
        "location": "鱼人岛龙宫王国",
        "key_figures": ["尼普顿", "乙姬王妃"]
      },
      {
        "age": "成年期",
        "event": "加入太阳海贼团，随费舍尔·泰格出航，与人类海军战斗；泰格死后接任船长，接受世界政府邀请成为王下七武海，保护鱼人岛免受侵袭",
        "location": "鱼人岛及伟大航路",
        "key_figures": ["费舍尔·泰格", "恶龙", "白胡子"]
      }
    ],
    "relationships": {
      "费舍尔·泰格": "太阳海贼团创始人，甚平的老大和导师",
      "恶龙": "前太阳海贼团同伴，因理念不合分道扬镳",
      "尼普顿": "鱼人岛国王，曾为甚平的上司",
      "乙姬王妃": "鱼人岛王妃，倡导与人类和平共处",
      "白胡子": "庇护鱼人岛的恩人，甚平对其心存感激"
    },
    "skills": {
      "鱼人空手道·唐草瓦正拳": "利用正拳产生全方位冲击波",
      "鱼人空手道·五千枚瓦正拳": "足以劈开五千枚瓦片威力的拳头",
      "鱼人空手道·枪波": "远距离发射水波，威力如炮弹",
      "鱼人柔术·水心·海流过肩摔": "操控海水引发大浪的过肩摔技",
      "鱼人空手道·奥义·武赖贯": "凝聚重水球贯穿敌人身体的终极招式"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "行侠仗义",
          "description": "人称“海侠”，富有正义感，常保护弱小"
        },
        {
          "trait": "责任感强",
          "description": "为守护鱼人岛和伙伴，愿承担重担"
        },
        {
          "trait": "冷静果断",
          "description": "面对危机时能沉着应对，决策果断"
        }
      ],
      "likes": [
        "和平",
        "鱼人岛居民",
        "公正义理"
      ],
      "dislikes": [
        "种族歧视",
        "背叛",
        "战争"
      ],
      "habits": [
        "练习鱼人空手道",
        "穿浴衣和木屐",
        "与海洋生物交流"
      ]
    },
    "lifestyle": "作为七武海和海贼船长，日常处理海贼团事务，保护鱼人岛，练习武技",
    "desire": "维护鱼人岛和平，促进鱼人与人类和谐共处",
    "appearance": {
      "overall_impression": "鲸鲨鱼人，蓝色皮肤，身材肥大强壮，气场威严",
      "face": "狂风般黑色眉毛和鬓角，左眼有闪电状伤痕，下颚两颗大牙突出，短发丁髷发型",
      "body_type": "身高301厘米，体型魁梧，肌肉发达，胸口有太阳海贼团标志",
      "hair": "黑色短发，梳成丁髷式",
      "eyes": "圆形眼睛，眼神坚定",
      "dressing_style": "常穿橙色花纹浴衣，外披红色披风，腰系紫色腰带，脚踏木屐",
      "skin": "蓝色皮肤，质地粗糙，符合鱼人族特征"
    }
  }
}

