      "沙岚": "形成沙风暴攻击，可控制行进方向",
      "沙漠宝刀": "将手臂变成沙刃斩击，锋利度可切开地面",
      "侵蚀轮回": "大范围吸干水分，使周围环境沙化"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "自信傲慢",
          "description": "相信自身实力，喜欢玩弄对手，但易因过度自信低估敌人"
        },
        {
          "trait": "残忍果断",
          "description": "对失去利用价值者毫不留情，行事狠辣"
        },
        {
          "trait": "精于谋略",
          "description": "擅长设计复杂计划，如理想乡作战，环环相扣"
