      ],
      "likes": [
        "权力",
        "雪茄",
        "鳄鱼肉",
        "番茄"
      ],
      "dislikes": [
        "失败",
        "背叛",
        "海军"
      ],
      "habits": [
        "抽雪茄",
        "使用金钩战斗",
        "策划阴谋"
      ]
    },
    "lifestyle": "作为犯罪集团首领，经营雨地赌场，日常抽雪茄、指挥部下，精于谋划",
    "desire": "成为海贼王，获取古代兵器冥王",
    "appearance": {
      "overall_impression": "高大威猛，身高253cm，左手为金钩，面带伤疤，常叼雪茄，尽显霸气",
      "face": "大背头发型，脸上有横断长伤疤，右耳戴耳环，五官硬朗",
      "body_type": "身高253cm，体型健壮，肌肉结实",
      "hair": "黑色大背头，发质硬挺",
      "eyes": "锐利双眼，眼神凶狠",
      "dressing_style": "常穿绿色长毛披风，内搭橙色格子衬衫，黑色裤子配金色扣环鞋子",
      "skin": "肤色偏深，因沙漠环境略显粗糙"
    }
  }
}

