        "location": "神之峡谷",
        "key_figures": ["安布里奥·伊万科夫", "金妮"]
      },
      {
        "age": "青年期",
        "event": "成为一名牧师，利用肉球果实能力免费为老人消除病痛。后因索尔贝王国的暴政被捕，被蒙奇·D·龙领导的革命军所救，随后与金妮一同加入革命军",
        "location": "南海索尔贝王国",
        "key_figures": ["金妮", "蒙奇·D·龙", "安布里奥·伊万科夫"]
      },
      {
        "age": "成年期",
        "event": "金妮被天龙人掳走病故后，受托抚养其女波妮。为救治波妮的绝症“青玉鳞”，与世界政府科学家贝加庞克达成协议，以自身接受改造为条件换取治疗。后成为王下七武海，并自愿被完全改造为无意识的和平主义者PX-0",
        "location": "索尔贝王国、未来岛等",
        "key_figures": ["乔艾莉·波妮（养女）", "Dr. 贝加庞克", "五老星"]
      }
    ],
    "relationships": {
      "库拉普": "父亲，巴卡尼亚族，同为天龙人奴隶，在大熊幼年时被杀害",
      "金妮": "革命军同伴，挚爱，波妮的亲生母亲，后被天龙人掳走并病故",
      "乔艾莉·波妮": "养女，视为己出，愿为其付出一切",
      "蒙奇·D·龙": "革命军领袖，战友",
      "安布里奥·伊万科夫": "革命军干部，自幼相识的挚友",
      "Dr. 贝加庞克": "世界政府科学家，对其进行改造的人"
    },
    "skills": {
      "肉球果实能力": "手掌有熊掌肉球，可弹开一切物体，包括攻击、痛苦、疲劳，并能将人或物体以光速拍飞至指定地点",
      "压力炮": "高速击出熊掌状冲击波进行远程攻击",
      "熊掌冲击": "压缩大气形成巨大冲击波，威力足以摧毁岛屿",
      "瞬间移动": "通过弹开空气实现高速移动",
      "武装色霸气": "能够提升自身的防御力和攻击力"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "沉默温柔",
          "description": "外表沉默寡言，内心却极为善良温柔，曾作为牧师无私帮助他人，对波妮充满深沉的父爱"
        },
        {
          "trait": "坚韧牺牲",
          "description": "为保护所爱之人和国家，甘愿承受巨大痛苦，牺牲自己的自由、肉体乃至意识"
        },
        {
          "trait": "沉着冷静",
          "description": "遇事极为冷静，行动富有计划性，即使在七武海时期也暗中执行自己的目标"
        }
      ],
      "likes": [
        "阅读（常手持圣经）",
        "和平",
        "帮助他人",
        "养女波妮"
      ],
      "dislikes": [
        "不公正与压迫",
        "世界政府/天龙人的暴行",
        "战争与伤害"
      ],
      "habits": [
        "手持书籍《BIBLE》",
        "使用能力前询问“要旅行的话，你想去哪里？”",
        "默默承受痛苦"
      ]
    },
    "lifestyle": "在完全改造前，作为七武海和革命军双面间谍活动，大部分时间用于执行任务和研究改造。常独自行动，手持书本阅读",
    "desire": "治愈养女波妮的疾病，让她能平安幸福地生活；推翻世界政府的暴政，实现真正的和平",
    "appearance": {
      "overall_impression": "体型异常高大魁梧，压迫感十足，但举止间透着与外表反差巨大的沉静与温和",
      "face": "方脸，面容刚毅，戴着一副无框眼镜，表情通常平静无波，左颈有“PX-0”纹样",
      "body_type": "身高689cm，身材极为壮硕，肌肉发达，是巴卡尼亚族混血的典型巨人体格",
      "hair": "黑色蓬松卷发，长度及肩",
      "eyes": "眼镜下的眼神通常难以看清，给人以深邃莫测之感",
      "dressing_style": "头戴梯形白色帽子，帽有棕色斑点及熊耳装饰。身穿印有准星图案的黑色外套，内着深色衣服，下身穿带斑点的白色长裤，脚蹬棕色靴子，手戴棕色手套",
      "skin": "肤色较深，手掌有粉色的肉球状软垫（肉球果实能力体现）"
    }
  }
}

