        "location": "西海及伟大航路",
        "key_figures": ["早期伙伴"]
      },
      {
        "age": "青年期",
        "event": "在和之国铃后地区与百兽海贼团交战，被凯多击败并失去所有同伴，受到重大打击",
        "location": "和之国铃后地区",
        "key_figures": ["凯多", "早期伙伴"]
      },
      {
        "age": "成年期",
        "event": "返回西海，在恐怖三桅帆船打造僵尸军团，招募霍古巴克、阿布萨罗姆和佩罗娜等部下，加入王下七武海",
        "location": "西海恐怖三桅帆船",
        "key_figures": ["霍古巴克", "阿布萨罗姆", "佩罗娜"]
      }
    ],
    "relationships": {
      "阿布萨罗姆": "部下，僵尸士兵与僵尸将军指挥官，忠诚于莫利亚",
      "霍古巴克": "部下，天才外科医生，以复活辛朵莉为条件加入",
      "佩罗娜": "部下，被莫利亚收养并当作女儿抚养",
      "凯多": "敌人，曾在和之国击败莫利亚，导致其伙伴全灭"
    },
    "skills": {
      "影影果实": "超人系恶魔果实，能操纵并掌控影子，可剪取影子、制造僵尸等",
      "影切": "用特制剪刀剪下他人影子的技能",
      "影法师": "影子分身，无视伤害，用于防御和攻击",
      "碎片蝙蝠": "将影子分裂成蝙蝠型影子进行咬噬或防御",
      "影子集合地": "吸入大量影子提升力量，但需要强大精神力控制"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "依赖性强",
          "description": "喜欢依靠部下的力量，自己坐享其成，疏于个人锻炼"
        },
        {
          "trait": "懒散拖沓",
          "description": "行事效率低，常拖延任务，但野心未消"
        },
        {
          "trait": "珍惜部下",
          "description": "对忠诚部下如阿布萨罗姆等人格外重视，愿为他们冒险"
        }
      ],
      "likes": [
        "鱼子酱腌泡汁",
        "僵尸军团",
        "坐享其成",
        "黑暗环境"
      ],
      "dislikes": [
        "失去同伴",
        "阳光直射",
        "努力锻炼",
        "被轻视"
      ],
      "habits": [
        "在恐怖三桅帆船上沉睡",
        "命令部下处理杂务",
        "使用影影果实练习能力"
      ]
    },
    "lifestyle": "作为海贼船长，日常在恐怖三桅帆船上依赖部下管理僵尸军团，较少亲自行动，喜欢在阴暗环境中策划计划",
    "desire": "成为海贼王，但希望通过僵尸军团实现，避免因失去活人伙伴而痛苦",
    "appearance": {
      "overall_impression": "体型庞大，身高692cm，是历任王下七武海中最高的。前额两侧有尖角，面部至颈部有垂直缝合线，颈部粗长，下半身肥胖短粗",
      "face": "尖耳朵和牙齿，尖下巴，嘴唇紫色，肤色淡蓝",
      "body_type": "身高692cm，上半身粗壮，下半身短粗，体重未知但显肥胖",
      "hair": "火葱状红紫色头发，短发直立",
      "eyes": "小眼睛，瞳孔颜色未明，常显凶悍",
      "dressing_style": "黑色宽大披风，内搭白色荷叶边服饰，系紫色十字架，下身穿橙黄色带方格图案的裤子，脚穿黑色皮鞋",
      "skin": "淡蓝色皮肤，触感未知但显粗糙"
    }
  }
}

