      "霍古巴克": "部下，天才外科医生，以复活辛朵莉为条件加入",
      "佩罗娜": "部下，被莫利亚收养并当作女儿抚养",
      "凯多": "敌人，曾在和之国击败莫利亚，导致其伙伴全灭"
    },
    "skills": {
      "影影果实": "超人系恶魔果实，能操纵并掌控影子，可剪取影子、制造僵尸等",
      "影切": "用特制剪刀剪下他人影子的技能",
      "影法师": "影子分身，无视伤害，用于防御和攻击",
      "碎片蝙蝠": "将影子分裂成蝙蝠型影子进行咬噬或防御",
      "影子集合地": "吸入大量影子提升力量，但需要强大精神力控制"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "依赖性强",
          "description": "喜欢依靠部下的力量，自己坐享其成，疏于个人锻炼"
        },
        {
          "trait": "懒散拖沓",
          "description": "行事效率低，常拖延任务，但野心未消"
        },
        {
          "trait": "珍惜部下",
          "description": "对忠诚部下如阿布萨罗姆等人格外重视，愿为他们冒险"
