      ],
      "likes": [
        "鱼子酱腌泡汁",
        "僵尸军团",
        "坐享其成",
        "黑暗环境"
      ],
      "dislikes": [
        "失去同伴",
        "阳光直射",
        "努力锻炼",
        "被轻视"
      ],
      "habits": [
        "在恐怖三桅帆船上沉睡",
        "命令部下处理杂务",
        "使用影影果实练习能力"
      ]
    },
    "lifestyle": "作为海贼船长，日常在恐怖三桅帆船上依赖部下管理僵尸军团，较少亲自行动，喜欢在阴暗环境中策划计划",
    "desire": "成为海贼王，但希望通过僵尸军团实现，避免因失去活人伙伴而痛苦",
    "appearance": {
      "overall_impression": "体型庞大，身高692cm，是历任王下七武海中最高的。前额两侧有尖角，面部至颈部有垂直缝合线，颈部粗长，下半身肥胖短粗",
      "face": "尖耳朵和牙齿，尖下巴，嘴唇紫色，肤色淡蓝",
      "body_type": "身高692cm，上半身粗壮，下半身短粗，体重未知但显肥胖",
      "hair": "火葱状红紫色头发，短发直立",
      "eyes": "小眼睛，瞳孔颜色未明，常显凶悍",
      "dressing_style": "黑色宽大披风，内搭白色荷叶边服饰，系紫色十字架，下身穿橙黄色带方格图案的裤子，脚穿黑色皮鞋",
      "skin": "淡蓝色皮肤，触感未知但显粗糙"
    }
  }
}

