{
  "characters": {
    "name": "唐吉诃德·多弗朗明哥",
    "nicknames": [
      "天夜叉",
      "Joker",
      "海流氓",
      "鸟人"
    ],
    "gender": "Male",
    "orientation": "异性恋",
    "identities": [
      "原天龙人",
      "原王下七武海",
      "德雷斯罗萨国王",
      "唐吉诃德家族首领"
    ],
    "background": [
      {
        "age": "幼年期",
        "event": "生于天龙人世家，享有特权生活，后因父亲放弃特权迁离圣地玛丽乔亚，家庭陷入贫困，母亲病逝",
        "location": "圣地玛丽乔亚及北海",
        "key_figures": ["唐吉诃德·霍名古圣（父亲）", "母亲（已故）", "唐吉诃德·罗西南迪（弟弟）"]
      },
      {
        "age": "少年期",
        "event": "10岁时枪杀父亲，携带其首级试图返回玛丽乔亚被天龙人拒绝，立誓颠覆世界秩序",
        "location": "圣地玛丽乔亚及北海",
        "key_figures": ["唐吉诃德·霍名古圣", "天龙人"]
      },
      {
        "age": "青年期",
        "event": "结识托雷波尔等干部，获赠线线果实，成立唐吉诃德家族，开始发展地下势力，逐步掌控北海黑道",
        "location": "北海",
        "key_figures": ["托雷波尔", "琵卡", "迪亚曼蒂", "维尔戈"]
      }
    ],
    "relationships": {
      "唐吉诃德·霍名古圣": "父亲，原天龙人，被多弗朗明哥亲手杀害",
      "唐吉诃德·罗西南迪": "弟弟，海军卧底，遭多弗朗明哥肃清",
      "托雷波尔": "唐吉诃德家族最高干部，如同家人",
      "琵卡": "唐吉诃德家族最高干部，忠诚部下",
      "迪亚曼蒂": "唐吉诃德家族最高干部，负责竞技场事务",
      "维尔戈": "唐吉诃德家族初代红心，海军内部间谍"
    },
    "skills": {
      "线线果实": "超人系恶魔果实，能操控肉眼不可见的丝线，进行切割、操控与防御",
      "五色线": "从五指发射锐利丝线，近战撕裂对手",
      "鸟笼": "用丝线构成巨大牢笼，收缩后可绞杀范围内一切目标",
      "霸王色霸气": "与生俱来的王者资质，可震慑敌人",
      "武装色霸气": "强化攻击与防御，能触及自然系能力者实体",
      "见闻色霸气": "预知对手动作，感知周围气息"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "桀骜不驯",
          "description": "自信傲慢，视规则如无物，习惯以力量碾压一切反对者"
        },
        {
          "trait": "残暴冷酷",
          "description": "为达目的不择手段，可舍弃亲人或部下，对敌人毫不留情"
        },
        {
          "trait": "谋略深沉",
          "description": "善于布局，通过地下交易与政治操纵扩大势力"
        }
      ],
      "likes": [
        "权力与控制",
        "地下交易",
        "颠覆秩序",
        "火烈鸟（象征物）"
      ],
      "dislikes": [
        "背叛",
        "弱者呻吟",
        "天龙人特权制度（尽管曾属其中）",
        "和平主义"
      ],
      "habits": [
        "身穿粉色羽毛大衣",
        "佩戴太阳眼镜",
        "习惯性发出“咈咈咈”笑声",
        "用手指细微操控丝线"
      ]
    },
    "lifestyle": "作为德雷斯罗萨国王与地下世界中介，日常处理政务与军火交易，通过电话虫远程指挥家族势力",
    "desire": "颠覆天龙人统治，将世界搅得天翻地覆，建立以自身为顶点的新时代",
    "appearance": {
      "overall_impression": "身高305cm，体型高大健硕，金发后梳，常戴反光太阳镜，粉色羽毛大衣张扬夺目，姿态傲慢且充满压迫感",
      "face": "面部轮廓锋利，鼻梁高挺，嘴角常挂讥讽笑容，太阳镜遮挡眼神，但透出冷酷气息",
      "body_type": "身高305cm，肌肉结实，肩宽腿长，站立时如猎豹般蓄势待发",
      "hair": "金色长发向后梳理整齐，发质硬朗有光泽",
      "eyes": "被太阳镜完全遮挡，推测为锐利双眼，目光如炬",
      "dressing_style": "粉色羽毛大衣搭配九分裤与尖头鞋，大衣敞开露出胸膛，强调狂放不羁的贵族气质",
      "skin": "肤色偏白，因天龙人血统保养得宜，触感平滑但隐含戾气"
    }
  }
}

