entries.content:
{
  "characters": {
    "name": "巴基",
    "nicknames": [
      "小丑巴基"
    ],
    "gender": "Male",
    "orientation": "异性恋",
    "identities": [
      "原罗杰海贼团实习生",
      "巴基海贼团船长"
    ],
    "background": [
      {
        "age": "少年期",
        "event": "在哥尔·D·罗杰的船上担任实习生，与香克斯共同成长，但因香克斯导致其误食四分五裂果实并丢失珍贵藏宝图，而对香克斯心生怨恨",
        "location": "罗杰海贼团船上",
        "key_figures": ["哥尔·D·罗杰", "西尔巴兹·雷利", "香克斯"]
      },
      {
        "age": "青年期",
        "event": "罗杰被处刑后，拒绝香克斯的邀请，独立组建巴基海贼团，主要在东海活动，并占领了橘子镇称王称霸",
        "location": "东海，特别是罗格镇、橘子镇",
        "key_figures": ["香克斯", "摩奇", "卡巴吉"]
      }
    ],
    "relationships": {
      "哥尔·D·罗杰": "前船长，极为尊敬",
      "香克斯": "曾经的实习船员同伴，因旧怨而关系复杂，既是故友也是竞争对手",
      "亚尔丽塔": "重要的合作伙伴，在逃离海军追捕后结成同盟",
      "Mr.3（加尔迪诺）": "推进城越狱的共犯，后成为巴基速递的干部",
      "摩奇": "巴基海贼团驯兽师，元老干部",
      "卡巴吉": "巴基海贼团杂技剑士，元老干部"
    },
    "skills": {
      "四分五裂果实能力": "超人系恶魔果实，能将身体任意部分分裂并操控，免疫大多数斩击，分裂部分需在脚部半径200公尺内控制",
      "四分五裂·飞刀":  "将持刀的手臂分裂飞出攻击敌人",
      "四分五裂·炮": "将分裂的身体部位高速投掷攻击",
      "巴基弹": "特制的大威力炮弹，可摧毁半个城镇",
      "特制巴基弹": "体积小但破坏力惊人的便携式炸弹"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "狡猾投机",
          "description": "善于审时度势，利用一切机会为自己谋利，常在不利局面下巧妙脱身甚至扭转局势"
        },
        {
          "trait": "虚荣自负",
          "description":  "享受他人的追捧和崇拜，在意名声，但实力与野心时常不匹配"
        },
        {
          "trait": "记仇贪财",
          "description": "对得罪过自己的人（如路飞、香克斯）耿耿于怀，同时对财宝有极强的渴望"
        }
      ],
      "likes": [
        "财宝与贝利",
        "被人奉承",
        "开宴会",
        "收集藏宝图"
      ],
      "dislikes": [
        "别人谈论他的红鼻子",
        "香克斯",
        "蒙奇·D·路飞",
        "计划被打乱"
      ],
      "habits": [
        "计划获取财宝",
        "在高兴时开宴会庆祝",
        "用手下当挡箭牌"
      ]
    },
    "lifestyle": "作为海贼船长领导部下，热衷于寻找宝藏和扩大势力，经营海贼派遣业务，生活方式浮夸且注重排场",
    "desire": "获得世界上所有的财宝，成为受人敬畏的大海贼",
    "appearance": {
      "overall_impression": "造型夸张醒目的小丑风格海贼，红鼻子是其最显著特征，体态高瘦，动作浮夸",
      "face": "长脸，化有小丑妆，蓝色泪滴状面纹和红色嘴唇，最突出的是巨大的圆球状红鼻子，表情丰富搞怪",
      "body_type": "身高192cm，体型瘦高，四肢修长",
      "hair": "蓝色长发，通常编成两根辫子从标志性的小丑帽两侧垂下",
      "eyes": "眼睛不大，但常因情绪而瞪大或眯起，瞳色为深色",
      "dressing_style": "头戴红白相间的小丑帽，身穿红白条纹上衣，外披白色船长外套（两年后改为用能力撑起的巨大红色斗篷），系紫绿色腰带，下着深紫色长裤，脚穿棕色长靴，戴白色手套",
      "skin": "肤色偏白，与妆容形成对比"
    }
  }
}

