      "卡利·达旦": "好友，代为照顾艾斯和路飞"
    },
    "skills": {
      "爱之铁拳": "缠绕霸气的拳头攻击，用于教育孙子和战斗",
      "拳骨陨石": "徒手投掷炮弹，威力强于军舰主炮",
      "拳骨流星群": "连续投掷炮弹的群体攻击",
      "拳骨冲击": "跳跃空中用霸气拳头范围攻击",
      "海底落下": "将对手投掷地面造成巨大冲击",
      "武装色霸气": "顶级霸气使用者，防御与攻击兼备",
      "见闻色霸气": "敏锐感知周围气息",
      "霸王色霸气": "数百万人之一的王者资质"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "刚正不阿",
          "description": "坚守正义信念，性格刚烈直率"
        },
        {
          "trait": "幽默风趣",
          "description": "性格开朗，常带着笑容，幽默感强"
        },
        {
          "trait": "重情重义",
          "description": "关心部下和家人，虽立场不同但仍深爱子孙"
        }
      ],
      "likes": [
        "仙贝",
        "喝茶",
        "训练新兵",
        "正义"
      ],
      "dislikes": [
        "邪恶",
        "不公正",
        "天龙人的傲慢"
      ],
      "habits": [
        "说着话突然睡着",
        "投掷炮弹训练",
        "戴着狗头帽子"
      ]
    },
    "lifestyle": "作为海军中将处理军务，训练新兵，闲暇时喝茶吃仙贝",
    "desire": "维护海军正义，培养新一代海军精英",
    "appearance": {
      "overall_impression": "身材高大健壮的老兵，灰白色短发，左眼伤疤，常戴狗头帽披正义披风",
      "face": "方脸轮廓分明，左眼上方有明显伤疤，蓝色眼睛，常带爽朗笑容",
      "body_type": "身高287cm，肌肉发达胸膛宽阔，体型魁梧有力",
      "hair": "灰白色短发，发型利落",
      "eyes": "蓝色眼睛，目光锐利有神",
      "dressing_style": "白色海军制服，披海军正义披风，肩垫黑红相间，戴标志性狗头帽子",
      "skin": "健康的小麦肤色，因常年征战留有伤痕"
    }
  }
}

