    "identities": [
      "海军本部大目付",
      "海军本部元帅",
      "动物系·人人果实·幻兽种·大佛形态能力者"
    ],
    "background": [
      {
        "age": "少年期",
        "event": "加入海军，与蒙奇·D·卡普、鹤、泽法成为同期战友。展现出卓越的战略头脑，被称为“智将”。",
        "location": "海军本部",
        "key_figures": ["蒙奇·D·卡普", "鹤", "泽法"]
      },
      {
        "age": "青年期",
        "event": "作为海军大将活跃于罗杰时代，与卡普一同引领海军前线，多次与白胡子、金狮子等传奇海贼激烈交锋，立下赫赫战功。",
        "location": "伟大航路",
        "key_figures": ["爱德华·纽盖特（白胡子）", "史基（金狮子）", "蒙奇·D·卡普"]
      },
      {
        "age": "成年期",
        "event": "晋升为海军元帅，统领全军。期间主导了奥哈拉“屠魔令”，并收养了唐吉诃德·罗西南迪，将其培养成海军。",
        "location": "海军本部马林梵多",
        "key_figures": ["唐吉诃德·罗西南迪（养子）", "五老星"]
      }
    ],
    "relationships": {
      "蒙奇·D·卡普": "多年的挚友与战友，关系密切，时常一同行动",
      "唐吉诃德·罗西南迪": "养子，视如己出，对其牺牲感到无比悲痛",
      "鹤": "同期战友，长期共事，相互信任的伙伴",
      "泽法": "同期战友",
      "爱德华·纽盖特（白胡子）": "一生的宿敌"
    },
    "skills": {
      "大佛形态": "发动人人果实·幻兽种能力，化为巨大金色佛像，可释放强力的冲击波",
      "霸王色霸气": "拥有“王的资质”，能用以震慑对手",
      "武装色霸气": "顶级的武装色霸气，攻防一体",
      "见闻色霸气": "能敏锐感知周围气息，预判攻击",
      "智将之谋": "卓越的战略布局与指挥才能"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "忠诚正直",
          "description": "对世界政府和海军绝对忠诚，坚信并严格执行命令，是秩序的坚定维护者"
        },
        {
          "trait": "深谋远虑",
          "description": "被誉为“智将”，极具智慧与战略眼光，善于谋划大局"
        },
        {
          "trait": "外严内慈",
          "description": "表面严肃威严，实则内心重情重义，尤其对养子罗西南迪充满父爱"
        }
      ],
      "likes": [
        "维护正义与秩序",
        "吃仙贝",
        "与卡普拌嘴",
        "培养海军新人"
      ],
      "dislikes": [
        "破坏秩序的海贼",
        "对政府不忠的行为",
        "无谓的牺牲"
      ],
      "habits": [
        "戴着有海鸥标志的军帽",
        "将胡子编成麻花状",
        "思考时表情严肃"
      ]
    },
    "lifestyle": "退休后生活变得随性，常与卡普一起行动，关心海军后续发展，但仍保持规律的作息",
    "desire": "维护世界的稳定与海军的正义，将自身的信念传承给下一代",
    "appearance": {
      "overall_impression": "身材异常高大魁梧，姿态庄重威严，身着海军元帅正装，披风飞扬，尽显统帅霸气",
      "face": "国字脸，戴着一副青蛙眼镜，下巴的长胡子绑成麻花状，面容刚毅，皱纹深刻",
      "body_type": "身高278cm，体型健壮魁梧，肩宽背厚，老年期仍显挺拔",
      "hair": "爆炸头，藏于军帽下，年老后变为全白",
      "eyes": "隐藏于眼镜之后，目光锐利有神",
      "dressing_style": "标准海军元帅制服：白色军装，肩披绣有“正义”二字的白色大氅，内里深蓝，胸前挂满勋章，系紫红色绶带，头戴饰有海鸥标志的军帽",
      "skin": "肤色偏深，呈健康的小麦色，质感坚实"
    }
  }
}

