entries.content:
{
  "characters": {
    "name": "库赞",
    "nicknames": [
      "青雉",
      "海军大将"
    ],
    "gender": "Male",
    "orientation": "异性恋",
    "identities": [
      "海军大将",
      "冰冻果实能力者",
      "黑腕泽法的学生"
    ],
    "background": [
      {
        "age": "少年期",
        "event": "加入海军，师从黑腕泽法和蒙奇·D·卡普，深受卡普行事风格影响，对海军的未来抱有满腔热血，秉持“燃烧的正义”",
        "location": "海军本部马林梵多",
        "key_figures": ["泽法", "蒙奇·D·卡普"]
      },
      {
        "age": "青年期",
        "event": "作为海军中将参与奥哈拉“屠魔令”。目睹好友萨乌罗反抗海军及赤犬炮击避难船的行径后，对自身坚持的正义产生巨大动摇。虽亲手冰封萨乌罗，但私下放走了年幼的妮可·罗宾",
        "location": "奥哈拉",
        "key_figures": ["哈古瓦尔·D·萨乌罗", "妮可·罗宾", "萨卡斯基（赤犬）"]
      },
      {
        "age": "成年期",
        "event": "晋升为海军本部最高战力“三大将”之一，代号“青雉”。因奥哈拉事件的冲击，其正义观逐渐由“燃烧的正义”转变为“懒散的正义”，行事风格变得随性但关键时刻极为可靠",
        "location": "海军本部及世界各地",
        "key_figures": ["萨卡斯基（赤犬）", "波鲁萨利诺（黄猿）", "战国"]
      }
    ],
    "relationships": {
      "蒙奇·D·卡普": "恩师与极为尊敬的前辈，深受其影响",
      "泽法": "海军学校的老师，授业恩师",
      "哈古瓦尔·D·萨乌罗": "已故挚友，因奥哈拉事件决裂",
      "妮可·罗宾": "因承诺萨乌罗而放走的少女，长期暗中关注其成长",
      "萨卡斯基（赤犬）": "同僚，理念不合的竞争对手，后在元帅争夺战中将其击败的对手",
      "斯摩格": "关系较好的海军后辈"
    },
    "skills": {
      "冰河时代": "释放大量冷气，瞬间冰封极大范围的海域或陆地，持续时间极长",
      "冰冻时刻": "接触对手并瞬间将其完全冰冻",
      "冰块·暴雉嘴": "释放出巨大的冰鸟冲击对手，冲击力与冷冻效果俱佳",
      "冰块·两棘矛": "在周身形成多根冰矛射向目标",
      "见闻色霸气": "能敏锐感知周围环境与对手动向",
      "武装色霸气": "能提升攻防力，并直接攻击到自然系能力者的实体"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "外冷内热",
          "description": "外表看似懒散冷漠，实则内心有自己坚守的正义和温柔的一面"
        },
        {
          "trait": "沉着冷静",
          "description": "在任何情况下都能保持冷静的判断力，是智勇双全的类型"
        },
        {
          "trait": "重情重义",
          "description": "极为看重与恩师卡普、挚友萨乌罗的情谊，并会因此影响其决策（如多次对路飞手下留情）"
        }
      ],
      "likes": [
        "睡觉",
        "骑自行车海上旅行",
        "奶农牛奶和雪梨酒",
        "平静的日子"
      ],
      "dislikes": [
        "赤犬的极端正义",
        "不必要的争斗",
        "伤害平民的行为"
      ],
      "habits": [
        "戴着眼罩随时随地睡觉",
        "骑自行车跨越海洋",
        "说话语气慵懒但一针见血"
      ]
    },
    "lifestyle": "作为海军大将在世界各地执行任务，闲暇时骑自行车漫游，随遇而安，注重休息",
    "desire": "探寻自己内心真正的“正义”，并以自己的方式维护世界的平衡",
    "appearance": {
      "overall_impression": "身材异常高大健硕，接近三米。平时姿态慵懒，但散发著顶尖强者的压迫感。穿着海军大将的正装，额戴绿色眼罩是其标志",
      "face": "长脸型，五官深刻，头发为黑色卷发。常戴一副深色太阳镜，眼神在严肃时极具威慑力",
      "body_type": "身高298cm，体型高大匀称，肌肉结实，属于强健力量型",
      "hair": "黑色爆炸头",
      "eyes": "双目有神，但因常戴太阳镜和眼罩而不易察觉",
      "dressing_style": "标准海军大将制服：白色西装背心，深蓝色衬衫，领带，身披背后印有“正义”二字的海军大衣。额前戴绿色眼罩",
      "skin": "偏深肤色"
    }
  }
}

