      "哈古瓦尔·D·萨乌罗": "已故挚友，因奥哈拉事件决裂",
      "妮可·罗宾": "因承诺萨乌罗而放走的少女，长期暗中关注其成长",
      "萨卡斯基（赤犬）": "同僚，理念不合的竞争对手，后在元帅争夺战中将其击败的对手",
      "斯摩格": "关系较好的海军后辈"
    },
    "skills": {
      "冰河时代": "释放大量冷气，瞬间冰封极大范围的海域或陆地，持续时间极长",
      "冰冻时刻": "接触对手并瞬间将其完全冰冻",
      "冰块·暴雉嘴": "释放出巨大的冰鸟冲击对手，冲击力与冷冻效果俱佳",
      "冰块·两棘矛": "在周身形成多根冰矛射向目标",
      "见闻色霸气": "能敏锐感知周围环境与对手动向",
      "武装色霸气": "能提升攻防力，并直接攻击到自然系能力者的实体"
    },
    "personality": {
      "core_traits": [
        {
          "trait": "外冷内热",
          "description": "外表看似懒散冷漠，实则内心有自己坚守的正义和温柔的一面"
        },
        {
          "trait": "沉着冷静",
          "description": "在任何情况下都能保持冷静的判断力，是智勇双全的类型"
        },
        {
          "trait": "重情重义",
          "description": "极为看重与恩师卡普、挚友萨乌罗的情谊，并会因此影响其决策（如多次对路飞手下留情）"
