        "奶农牛奶和雪梨酒",
        "平静的日子"
      ],
      "dislikes": [
        "赤犬的极端正义",
        "不必要的争斗",
        "伤害平民的行为"
      ],
      "habits": [
        "戴着眼罩随时随地睡觉",
        "骑自行车跨越海洋",
        "说话语气慵懒但一针见血"
      ]
    },
    "lifestyle": "作为海军大将在世界各地执行任务，闲暇时骑自行车漫游，随遇而安，注重休息",
    "desire": "探寻自己内心真正的“正义”，并以自己的方式维护世界的平衡",
    "appearance": {
      "overall_impression": "身材异常高大健硕，接近三米。平时姿态慵懒，但散发著顶尖强者的压迫感。穿着海军大将的正装，额戴绿色眼罩是其标志",
      "face": "长脸型，五官深刻，头发为黑色卷发。常戴一副深色太阳镜，眼神在严肃时极具威慑力",
      "body_type": "身高298cm，体型高大匀称，肌肉结实，属于强健力量型",
      "hair": "黑色爆炸头",
      "eyes": "双目有神，但因常戴太阳镜和眼罩而不易察觉",
      "dressing_style": "标准海军大将制服：白色西装背心，深蓝色衬衫，领带，身披背后印有“正义”二字的海军大衣。额前戴绿色眼罩",
      "skin": "偏深肤色"
    }
  }
}

